import cn from 'classnames';

type TabTogglerProps = {
  id: string;
  isActive: boolean;
  text: string;
  ariaControl: string;
};

function TabToggler({ id, isActive, ariaControl, text }: TabTogglerProps) {
  return (
    <li
      role="tab"
      id={id}
      className={cn('cmp-tabs__tab', { 'cmp-tabs__tab--active': isActive })}
      aria-controls={ariaControl}
      tabIndex={isActive ? 0 : -1}
      data-cmp-hook-tabs="tab"
      aria-selected={isActive}
    >
      {text}
    </li>
  );
}

export default TabToggler;
